const ALLOWED_ROUTES = new Set(["/orders", "/messages", "/settings"]);

function routeFrom(deepLink) {
  if (typeof deepLink !== "string") return "/home";
  const match = /^campus:\/\/([^/?#]+)(\/[^?#]*)?/.exec(deepLink);
  if (match === null) return "/home";
  const first = "/" + match[1];
  if (!ALLOWED_ROUTES.has(first)) return "/home";
  return first + (match[2] ?? "");
}

function buildPushPayload(message, deepLink) {
  const body = message.length > 80 ? message.slice(0, 77) + "..." : message;
  return {
    title: "Campus",
    body: body,
    data: { route: routeFrom(deepLink) },
  };
}
